#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Правки price.json за підсумками аналізу 02.09.2026 (docs/аналіз-прайсу.md, розділ 11).

Що робить: (1) прибирає формулювання поза периметром і звужує сумнівні пункти;
(2) додає UA-застереження (ПРРО, еквайринг, КЕП, кадри); (3) переписує ознаки рівнів
як відповіді на одне питання сейла і додає поле q; (4) додає bounds — «не входить»
по позиції; (5) додає dep/apps/home з deps-fragment.json; (6) уніфікує назви рівнів.
Годин і економії НЕ чіпає — це гіпотези для замірів фази 0.

Запуск з кореня репозиторію: python3 docs/аналіз-прайсу/скрипти/apply_fixes_2026-09-03.py
"""
import io, json, os, sys

ROOT = os.getcwd()
PRICE = os.path.join(ROOT, 'data', 'price.json')
FRAG = os.path.join(ROOT, 'docs', 'аналіз-прайсу', 'скрипти', 'deps-fragment.json')

p = json.load(io.open(PRICE, encoding='utf-8'))
items = {it['id']: it for g in p['групи'] for it in g['items']}
frag = json.load(io.open(FRAG, encoding='utf-8'))['позиції']

def rep(iid, where, old, new):
    """where: 'inc' або індекс рівня 1/2 (додані пункти)."""
    lst = items[iid]['inc'] if where == 'inc' else items[iid]['lv'][where][4]
    hits = [i for i, s in enumerate(lst) if s == old]
    assert len(hits) == 1, 'не знайдено або дубль: %s/%s «%s»' % (iid, where, old)
    lst[hits[0]] = new

