rep('web', 2, 'власні фільтри каталогу (Studio)', 'фільтри каталогу за атрибутами, тегами і ціною (штатно)')
rep('pos', 1, 'власні поля в чеку (Studio)', 'власний текст шапки й підвалу чека (штатно); власні поля замовлення POS для бекофісу (Studio)')
rep('rnt', 2, 'технологічна пауза між орендами; облік ТО по екземпляру — доопрацювання',
    'технологічна пауза між орендами (штатно); ТО об’єктів — заявками в застосунку «Обслуговування», без автоматичного зв’язку з орендою')
rep('rnt', 2, 'комплектація позиціями з серійниками; шаблон комплекту — доопрацювання',
    'комплектація позиціями з серійниками; типові комплекти — шаблонами пропозицій')
rep('dsh', 2, 'обчислювані поля на моделі — окрема оцінювана доробка',
    'зведений дашборд власника з показниками кількох застосунків (Spreadsheet)')
rep('prt', 2, 'поля бланка через Studio; умови всередині бланка — лише в XML',
    'поля бланка через Studio; замість умовних блоків — окремі бланки під варіанти документа')

