rep('hr', 2, 'кадрові документи', 'файли співробітника в Документах, версії умов найму; кадрові накази, табель і форми Держстату — поза периметром (BAS)')
rep('doc', 1, 'маршрути узгодження', 'узгодження документів через застосунок «Погодження» (запит із вкладенням і погоджувачами)')
rep('doc', 1, 'електронний підпис', 'простий електронний підпис Odoo Sign (не КЕП)')
rep('doc', 2, 'складні маршрути з умовами', 'кроки погодження з умовами й порядком (Studio approvals); маршрути з розгалуженнями й ескалаціями — немає')
rep('doc', 2, 'шаблони документів', 'шаблони для підпису (Sign); документ із реквізитами запису — друкованим бланком (позиція «Друковані форми»)')
rep('diag', 'inc', 'усна відповідь про строк і ціну', 'усна відповідь про строк і діапазон ціни; ціна фіксується письмово')
# «перелік того, чого не буде» — у всі рівні діагностики
items['diag']['lv'][1][4].remove('перелік того, чого не буде')
items['diag']['inc'].append('перелік того, чого не буде')

# ---------- 3. ознаки рівнів як відповіді на питання сейла ----------
